{
  "key": "{{lenderKey}}.working_capital",
  "name": {
    "en": "Lender X Working Capital"
  },
  "content": {
    "category": "business",
    "segments": [
      "msme"
    ],
    "subSegments": [
      "proprietorship",
      "partnership"
    ],
    "amountPaise": {
      "min": 50000000,
      "max": 500000000
    },
    "tenureMonths": {
      "min": 12,
      "max": 36
    },
    "coverage": {
      "states": [
        "06"
      ]
    },
    "eligibility": {
      "hard": [
        {
          "id": "vintage",
          "when": {
            "attr": "business.vintage_months",
            "op": "gte",
            "value": 24
          },
          "pass": {
            "en": "Business vintage fits their policy"
          },
          "fail": {
            "en": "They need 2 years of business history"
          }
        },
        {
          "id": "gst",
          "when": {
            "attr": "business.gst_registered",
            "op": "eq",
            "value": true
          },
          "fail": {
            "en": "They lend only to GST-registered businesses"
          }
        }
      ],
      "soft": [
        {
          "id": "turnover",
          "weight": 3,
          "minProvenance": "extracted",
          "when": {
            "attr": "business.monthly_turnover_paise",
            "op": "gte",
            "value": 50000000
          }
        }
      ]
    },
    "documents": [
      {
        "key": "udyam",
        "documentTypes": [
          "udyam_certificate"
        ],
        "stage": "submission"
      }
    ],
    "pricingDisclosure": {
      "en": "As per lender policy"
    }
  }
}

